import assert from 'assert';
import fs from 'fs';
import {constructorTypes,argumentError,declarationIssues,recordLiteral,builtinArrayType,typeSql} from './data-types.js';
import {generate,parseDraft,example} from './model.js';
import {parseWorkingSnapshot,encodeWorkingFile,parseWorkingFile} from './working-draft.js';
import {createTemplate} from './templates.js';
import {randomBytes} from 'crypto';
globalThis.crypto={randomUUID:()=>randomBytes(16).toString('hex')};
const cases=JSON.parse(fs.readFileSync(new URL('../../core/tests/fixtures/scalar-values.json',import.meta.url),'utf8'));
assert.equal(recordLiteral(['',null,'plain']),'("",,"plain")');
assert.equal(recordLiteral(['a,b','"q"','a\\b']),String.raw`("a,b","\"q\"","a\\b")`);
const named={schema:'Sales Q',name:'status "day"',array:true};
const typed=example();typed.parameters[0].type=named;typed.variables[0].type=builtinArrayType('integer');typed.returnType='jsonb';
assert.deepEqual(parseDraft(JSON.stringify(typed)),typed);
assert(generate(typed).sql.includes('"Sales Q"."status ""day"""[]'));
assert(generate(typed).sql.includes('"pg_catalog"."int4"[]'));
assert.equal(typeSql(typed.returnType),'jsonb');
assert.throws(()=>parseDraft(JSON.stringify({...typed,returnType:{...named,oid:42}})));
assert.deepEqual(parseDraft(JSON.stringify({...typed,returnType:{...named,array:false}})).returnType,{schema:named.schema,name:named.name});
for(const test of cases){
  assert(constructorTypes.includes(test.type));
  for(const value of test.valid)assert.equal(argumentError(test.oid,value),'',value);
  for(const value of test.invalid)assert(argumentError(test.oid,value),value);
  assert.equal(argumentError(test.oid,null),'');
  const p=example();p.returnType=test.type;p.parameters[0].type=test.type;p.variables[0].type=test.type;p.blocks=[{id:'r',type:'return',expression:'input_value'}];
  assert.deepEqual(parseDraft(JSON.stringify(p)),p);assert.equal(generate(p).errors.length,0);
}
const p=example();p.parameters.push({name:'running_total',type:'numeric'});p.variables.push({name:'',type:'invalid',initial:''});
const multiline=example();multiline.variables[0].initial='(\ninput_value\n)';const generated=generate(multiline),range=generated.sourceMap[multiline.blocks[0].id];assert(generated.sql.split('\n')[range.start-1].includes(':= running_total + 1'));
multiline.blocks[0].expression='(\ninput_value + 1\n)';multiline.blocks[2].expression='(\nrunning_total\n)';const mapped=generate(multiline),last=mapped.sourceMap[multiline.blocks[2].id];assert(mapped.sql.split('\n')[last.start-1].includes('RETURN'));assert.equal(last.bodyEnd-last.bodyStart,2);
const issues=declarationIssues(p);assert(issues.some(i=>i.key==='parameters'&&i.field==='name'));assert(issues.some(i=>i.key==='variables'&&i.field==='type'));
const value={project:p,selected:null,branch:'after',parametersText:'',variablesText:'',declarationsVersion:2};
assert.equal(parseWorkingFile(encodeWorkingFile(value)).project.variables[1].name,'');assert.equal(parseWorkingSnapshot(value).declarationsVersion,2);assert.throws(()=>parseWorkingSnapshot({...value,declarationsVersion:3}));
const context={relation:{oid:1,schema:'public',name:'precise',kind:'r',can_select_all:true},details:{columns:[{name:'id',number:1,type_oid:2950},{name:'amount',number:2,type_oid:1700,can_update:true}],foreign_keys:[]}};
const settings={schema:'public',table:'precise',mode:'value',column:{side:'source',name:'amount'},filter:{side:'source',name:'id',parameter:'input_id'},join:null};
const lookup=createTemplate(example(),settings,context,'lookup').project;assert.equal(lookup.returnType,'numeric');assert.equal(lookup.parameters[0].type,'uuid');
const sum=createTemplate(example(),{...settings,filter:null},context,'sum').project;assert.equal(sum.returnType,'numeric');
assert.equal(createTemplate(example(),settings,context,'status').project.parameters[1].type,'numeric');
console.log('PASS types: shared exact-value cases, field issues, unfinished form recovery and typed lookup/sum/status templates');
